# Generated by OrchestKit Claude Plugin
# Created: 2026-07-27

#!/usr/bin/env python3
"""Scanner half of the model-recency gate. Emits one JSON object on stdout.

The contract, the requirement-vs-history rules and the escape hatch are
documented in the header of test-model-recency.sh, which is the only intended
caller. This file is the implementation, kept out of the shell script because a
9 KB heredoc is a fragile way to ship 200 lines of Python.

Reads: $VOCAB_FILE (src/hooks/src/lib/models.vocab.json).
Scans: src/skills/**/*.md and src/agents/**/*.md, relative to the cwd.
Emits: counts + findings for three counters
       1. recommendations - ID-shaped `model=claude-opus-4-8` values
       2. prose_claims    - live prose claims ("requires Opus 4.8")
       3. cc_stamps       - hardcoded `CC 2.1.NN` in src/agents/*.md bodies
"""

import collections
import glob
import json
import os
import re

vocab = json.load(open(os.environ["VOCAB_FILE"], encoding="utf-8"))
aliases = vocab["aliases"]
full_ids = set(vocab["fullIds"])

TOKEN = r"claude-(?:fable|opus|sonnet|haiku)-[0-9][0-9a-z-]*"
CHANNEL_RE = re.compile(r"^claude-(fable|opus|sonnet|haiku)-")

# --- R1: the token is the VALUE of a model-ish key/argument -----------------
# An optional provider prefix (anthropic/, openrouter/anthropic/) is tolerated.
# No \b before `model` on purpose: it must also fire inside init_chat_model(...).
REC_RE = re.compile(
    r"(?:model(?:_?name|_?id)?|llm)[\"']?\s*[=:(]\s*[\"']?"
    r"(?:[a-z0-9_.-]+/)*"
    r"(" + TOKEN + r")",
    re.I,
)

# --- prose: "Opus 4.8", "Claude Sonnet 4.6", "Haiku 4.5" --------------------
# Case-sensitive channel names: prose uses the product name, and the hyphenated
# API ID has no space, so the two cannot collide.
PROSE_RE = re.compile(r"(?<![\w./-])(?:Claude\s+)?(Fable|Opus|Sonnet|Haiku)\s+(\d+(?:\.\d+)?)")

# --- counter 3: CC support-floor stamps in agent bodies ---------------------
CC_STAMP_RE = re.compile(r"\b(?:CC|Claude\s+Code)\s+v?(2\.1\.\d+)")

# --- universal skips (H4, H5, H6) ------------------------------------------
HISTORY_PATH_RE = re.compile(r"migration|migrate|upgrade|changelog|history|compat|version", re.I)
TABLE_ROW_RE = re.compile(r"^\s*(?:>\s*)*\|")
DIAGRAM_RE = re.compile(r"[└├│─]|\+--")
OPT_OUT_RE = re.compile(r"model-recency-ok:")

# H1: dated framing anywhere in the 60 characters before the mention.
HISTORY_CUE_RE = re.compile(
    r"\b(?:landed|shipped|introduced|arrived|launched|released|debuted|"
    r"added|deprecat\w*|retired|removed|superseded|replaced|renamed|dropped|"
    r"was|were|used\s+to|previously|formerly|originally|legacy|historic\w*|"
    r"prior\s+to|before|since|as\s+of|until|up\s+to|back\s+in|"
    r"older|earlier|migrat\w*|upgrad\w*|changelog)\b",
    re.I,
)

# H2: comparison immediately before the mention (short tail only, so
# "Filesystem vs MCP memory (Opus 4.8 ...)" is NOT read as a comparison).
COMPARISON_TAIL_RE = re.compile(
    r"(?:than|versus|vs\.?|compared\s+to|\d+\s*[x×])\s+"
    r"(?:the\s+|a\s+|what\s+)?(?:Claude\s+)?$",
    re.I,
)

# H3: floor form. A floor is satisfied by any newer release.
FLOOR_AHEAD_RE = re.compile(r"^\s*(?:\+|or\s+(?:newer|later|above|higher))")

# R2: present-tense predicate with the model as subject.
LIVE_PREDICATE_RE = re.compile(
    r"^\W{0,3}\s*(?:is|are|has|have|does|do|supports?|provides?|exposes?|"
    r"reads?|uses?|defaults?|enables?|allows?|handles?|adds?|carries|offers?|"
    r"requires?|needs?|ships|runs?|costs?|accepts?|returns?|can|will|now|"
    r"only)\b",
    re.I,
)

# R3: requirement verb/preposition governing the model (anchored tail).
REQUIREMENT_TAIL_RE = re.compile(
    r"(?:requires?|required|needs?|must\s+(?:be|use|run|have)|uses?|using|"
    r"run(?:s|ning)?\s+on|assumes?|expects?|targets?|only\s+(?:on|with|for)|"
    r"leverag\w+|powered\s+by|built\s+on|optimi[sz]ed\s+for|designed\s+for|"
    r"with|without|under|on)\s+(?:the\s+)?(?:Claude\s+)?$",
    re.I,
)

# R4: label position (heading, or before the line's first label colon).
HEADING_RE = re.compile(r"^\s{0,3}#{1,6}\s")
LABEL_COLON_RE = re.compile(r":(?=\s|\*|$)")

# R5: key-value where the model is the value ("**Auditor:** Claude Opus 4.8").
KEYVAL_RE = re.compile(
    r"^\s*(?:[-*+>]\s+)*(?:\*\*|\x60)?[A-Za-z][\w .()/-]{0,40}"
    r"(?:\*\*|\x60)?:\**\s*"
)


def current_for(token):
    """Alias target for this token's channel, or None if the channel is
    unknown."""
    m = CHANNEL_RE.match(token)
    return aliases.get(m.group(1)) if m else None


def superseded(token):
    """Valid but no longer the latest for its channel.

    A bare ID that the dated alias target extends (claude-haiku-4-5 vs
    claude-haiku-4-5-20251001) is the SAME model written without its snapshot
    date, so it is current, not superseded.
    """
    if token not in full_ids:
        return False
    cur = current_for(token)
    if cur is None or token == cur:
        return False
    return not cur.startswith(token + "-")


def prose_token(match):
    """ "Opus 4.8" -> claude-opus-4-8."""
    return "claude-%s-%s" % (match.group(1).lower(), match.group(2).replace(".", "-"))


# H2b: comparison AFTER the mention. COMPARISON_TAIL_RE only ever looked
# backwards, which caught the trailing model in "faster than Opus 4.6" but not
# the leading one in "Opus 4.8 is 3x faster than Opus 4.6" -- that first mention
# was reported as a live present-tense claim. A benchmark sentence is a dated
# observation about two models, not a requirement to run either of them, so both
# ends of the comparison must be exempt. Requires a second model mention in the
# tail so "Opus 4.8 is required" cannot slip through on the verb alone.
COMPARISON_AHEAD_RE = re.compile(
    r"^\s+(?:is|was|are|were|runs?|scores?|benchmarks?)?\s*"
    r"(?:\d+\s*[x×]\s*)?"
    r"(?:faster|slower|cheaper|better|worse|stronger|weaker|more|less)\b"
    r"[^.]{0,60}?\b(?:than|versus|vs\.?|compared\s+to)\b",
    re.IGNORECASE,
)


def reads_as_history(line, start, end=None):
    """H1 + H2 + H2b: is this mention framed as a dated claim?"""
    before = line[:start]
    if COMPARISON_TAIL_RE.search(before[-40:]):
        return True
    if end is not None and COMPARISON_AHEAD_RE.match(line[end:]):
        return True
    return bool(HISTORY_CUE_RE.search(before[-60:]))


def live_claim_reason(line, start, end):
    """R2-R5. Returns why the mention reads as a live claim, or None."""
    if FLOOR_AHEAD_RE.match(line[end:]):  # H3
        return None
    if reads_as_history(line, start, end):  # H1 + H2 + H2b
        return None
    if HEADING_RE.match(line):
        return "heading"
    colon = LABEL_COLON_RE.search(line)
    if colon and start < colon.start() <= 90:
        return "label"
    kv = KEYVAL_RE.match(line)
    if kv and kv.end() == start:
        return "key-value"
    if LIVE_PREDICATE_RE.match(line[end:]):
        return "present-tense claim"
    if REQUIREMENT_TAIL_RE.search(line[:start][-40:]):
        return "requirement verb"
    return None


def opted_out(lines, i):
    """H6: escape hatch on the line itself or the line directly above."""
    prev = lines[i - 1] if i else ""
    return bool(OPT_OUT_RE.search(lines[i]) or OPT_OUT_RE.search(prev))


def skipped_shape(line):
    """H5: table rows and ASCII diagrams enumerate, they do not recommend."""
    return bool(TABLE_ROW_RE.match(line) or DIAGRAM_RE.search(line))


def main():
    files = sorted(
        p
        for root in ("src/skills", "src/agents")
        for p in glob.glob("%s/**/*.md" % root, recursive=True)
    )

    findings = []  # counter 1: ID-shaped recommendations
    prose_findings = []  # counter 2: prose model claims
    cc_findings = []  # counter 3: CC stamps in agent bodies
    skipped_history_files = set()

    for path in files:
        history_path = bool(HISTORY_PATH_RE.search(path))
        # README.md under src/agents is GENERATED from agent descriptions, so
        # an offense there is a source problem in some description, not here.
        # Same carve-out as test-agent-no-version-snapshot.mjs.
        agent_body = (
            path.startswith("src/agents/")
            and path.count("/") == 2
            and not path.endswith("/README.md")
        )
        try:
            with open(path, encoding="utf-8", errors="ignore") as fh:
                lines = fh.read().splitlines()
        except OSError:
            continue

        for i, line in enumerate(lines):
            shape_skip = skipped_shape(line)
            opt_out = opted_out(lines, i)

            # ---- counter 1: ID-shaped recommendation ----------------------
            hits = [m.group(1) for m in REC_RE.finditer(line)]
            hits = [t for t in hits if superseded(t)]
            if hits:
                if history_path:
                    skipped_history_files.add(path)
                elif not shape_skip and not opt_out:
                    for token in hits:
                        findings.append(
                            {
                                "file": path,
                                "line": i + 1,
                                "token": token,
                                "current": current_for(token),
                                "why": "model= value",
                                "text": line.strip()[:110],
                            }
                        )

            # ---- counter 2: prose model claim -----------------------------
            if not history_path and not shape_skip and not opt_out:
                for m in PROSE_RE.finditer(line):
                    token = prose_token(m)
                    if not superseded(token):
                        continue
                    why = live_claim_reason(line, m.start(), m.end())
                    if why is None:
                        continue
                    prose_findings.append(
                        {
                            "file": path,
                            "line": i + 1,
                            "phrase": m.group(0),
                            "token": token,
                            "current": current_for(token),
                            "why": why,
                            "text": line.strip()[:110],
                        }
                    )

            # ---- counter 3: CC stamp in an agent body ---------------------
            if agent_body and not shape_skip and not opt_out:
                for m in CC_STAMP_RE.finditer(line):
                    if reads_as_history(line, m.start()):
                        continue
                    cc_findings.append(
                        {
                            "file": path,
                            "line": i + 1,
                            "stamp": m.group(0),
                            "version": m.group(1),
                            "text": line.strip()[:110],
                        }
                    )

    by_token = collections.Counter(f["token"] for f in findings)
    by_phrase = collections.Counter("%s (%s)" % (f["phrase"], f["why"]) for f in prose_findings)
    by_file = collections.Counter(f["file"] for f in (findings + prose_findings + cc_findings))

    print(
        json.dumps(
            {
                "files_scanned": len(files),
                "aliases": aliases,
                "recommendations": len(findings),
                "prose_claims": len(prose_findings),
                "cc_stamps": len(cc_findings),
                "files_affected": len(by_file),
                "by_token": dict(sorted(by_token.items(), key=lambda kv: -kv[1])),
                "by_phrase": dict(sorted(by_phrase.items(), key=lambda kv: -kv[1])),
                "by_file": dict(sorted(by_file.items(), key=lambda kv: (-kv[1], kv[0]))),
                "skipped_history_files": sorted(skipped_history_files),
                "findings": findings,
                "prose_findings": prose_findings,
                "cc_findings": cc_findings,
            }
        )
    )


if __name__ == "__main__":
    main()
